"""Depot: multi-warehouse inventory and cash ledger.

Every mutating operation is atomic: on failure the state is restored from a
snapshot taken before the operation. The snapshot taken before the last
successful mutating operation backs `undo()`.
"""

import copy
import decimal
import json
from decimal import Decimal

import money
from events import DepotError, EventLog
from money import Ledger
from suppliers import Suppliers

__all__ = ["Depot", "DepotError"]

_ROUNDING_MODES = (
    decimal.ROUND_UP,
    decimal.ROUND_DOWN,
    decimal.ROUND_CEILING,
    decimal.ROUND_FLOOR,
    decimal.ROUND_HALF_UP,
    decimal.ROUND_HALF_DOWN,
    decimal.ROUND_HALF_EVEN,
    decimal.ROUND_05UP,
)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _need_int(x):
    if not _is_int(x):
        raise ValueError("expected int")
    return x


def _pair(key):
    try:
        sku, wh = key
    except (TypeError, ValueError):
        raise DepotError("BAD_ARG")
    return sku, wh


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode,
                 late_penalty_pct=None):
        """`rounding_mode` is required (C31). `late_penalty_pct` is the owner's
        undecided percentage (C18); until it is set, late deliveries are refused
        with PENALTY_UNSET."""
        if rounding_mode not in _ROUNDING_MODES:
            raise ValueError("unknown rounding mode")
        whs = list(warehouses)
        if not whs or len(set(whs)) != len(whs):
            raise ValueError("warehouses must be a non-empty list of unique names")
        if set(capacities) != set(whs):
            raise ValueError("capacities must name exactly the warehouses")
        for c in capacities.values():
            if not _is_int(c) or c < 0:
                raise ValueError("capacity must be a non-negative int")
        if not _is_int(opening_cash):
            raise ValueError("opening_cash must be an int of cents")
        if late_penalty_pct is not None:
            p = Decimal(str(late_penalty_pct))
            if not (0 <= p <= 100):
                raise ValueError("late_penalty_pct must be in [0, 100]")
            late_penalty_pct = p

        self.warehouses = whs
        self.capacities = dict(capacities)
        self.rounding_mode = rounding_mode
        self.late_penalty_pct = late_penalty_pct
        self.items = {}            # sku -> {unit_cost, reorder_level, shelf_life}
        self.lots = {}             # (sku, wh) -> [[recv_day, qty], ...] FIFO
        self.armed = {}            # (sku, wh) -> bool (C14)
        self.sold_by_sku = {}      # units shipped via ship()
        self.returned_by_sku = {}  # units returned via return_goods()
        self.ledger = Ledger(opening_cash)
        self.suppliers = Suppliers()
        self.log = EventLog()
        self._day = 0
        self._undo = None          # snapshot for undo(); None means blocked

    # ------------------------------------------------------------------
    # read-only properties
    @property
    def cash(self):
        return self.ledger.cash

    @property
    def day(self):
        return self._day

    # ------------------------------------------------------------------
    # atomicity and undo
    def _capture(self):
        return copy.deepcopy({k: v for k, v in self.__dict__.items() if k != "_undo"})

    def _mutate(self, fn, *args, undoable=True):
        before = self._capture()
        try:
            result = fn(*args)
        except BaseException:
            self.__dict__.update(before)
            raise
        self._undo = before if undoable else None
        return result

    def undo(self):
        """C27: revert the last successful operation, once."""
        if self._undo is None:
            raise DepotError("UNDO_BLOCKED")
        snap = self._undo
        self.__dict__.update(snap)
        self._undo = None

    # ------------------------------------------------------------------
    # helpers
    def _item(self, sku):
        if sku not in self.items:
            raise DepotError("UNKNOWN_SKU")
        return self.items[sku]

    def _wh(self, wh):
        if wh not in self.capacities:
            raise DepotError("UNKNOWN_WAREHOUSE")

    @staticmethod
    def _check_qty(qty):
        if not _is_int(qty) or qty <= 0:
            raise DepotError("BAD_ARG")

    def _sku_wh_units(self, sku, wh):
        return sum(q for _, q in self.lots.get((sku, wh), []))

    def _wh_total(self, wh):
        return sum(q for (s, w), lots in self.lots.items() if w == wh for _, q in lots)

    def _total_units(self):
        return sum(q for lots in self.lots.values() for _, q in lots)

    def _take_fifo(self, sku, wh, qty):
        """Remove qty units from the oldest lots. Returns [(recv_day, taken)]."""
        key = (sku, wh)
        lots = self.lots.get(key, [])
        taken = []
        remaining = qty
        for lot in lots:
            if remaining == 0:
                break
            take = min(lot[1], remaining)
            taken.append((lot[0], take))
            lot[1] -= take
            remaining -= take
        self.lots[key] = [lot for lot in lots if lot[1] > 0]
        return taken

    def _reorder_check(self, sku, wh, outflow):
        """C14: emit REORDER once per fall through the level; re-arm above it."""
        key = (sku, wh)
        level = self.items[sku]["reorder_level"]
        units = self._sku_wh_units(sku, wh)
        if units > level:
            self.armed[key] = True
        elif outflow and self.armed.get(key, True):
            self.armed[key] = False
            self.log.emit("REORDER", sku, wh)

    def _do_receive(self, sku, qty, wh, cost):
        """Core receipt. `cost` is the amount paid to the supplier, in cents."""
        if self.ledger.cash < 0:
            raise DepotError("OVERDRAWN")                       # C20
        if self._wh_total(wh) + qty > self.capacities[wh]:
            raise DepotError("CAPACITY")                        # C04
        if self.ledger.cash - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")              # C05
        self.lots.setdefault((sku, wh), []).append([self._day, qty])
        self.ledger.cash -= cost
        self._reorder_check(sku, wh, outflow=False)

    def _do_receive_public(self, sku, qty, wh):
        item = self._item(sku)
        self._wh(wh)
        self._check_qty(qty)
        self._do_receive(sku, qty, wh, item["unit_cost"] * qty)

    # ------------------------------------------------------------------
    # catalogue
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        return self._mutate(self._do_add_item, sku, unit_cost, reorder_level, shelf_life_days)

    def _do_add_item(self, sku, unit_cost, reorder_level, shelf_life_days):
        if not isinstance(sku, str) or not sku:
            raise DepotError("BAD_ARG")
        if not _is_int(unit_cost) or unit_cost <= 0:           # C01
            raise DepotError("BAD_ARG")
        if not _is_int(reorder_level) or reorder_level < 0:
            raise DepotError("BAD_ARG")
        if shelf_life_days is not None and (not _is_int(shelf_life_days) or shelf_life_days < 0):
            raise DepotError("BAD_ARG")
        if sku in self.items:
            raise DepotError("DUPLICATE_SKU")
        self.items[sku] = {
            "unit_cost": unit_cost,
            "reorder_level": reorder_level,
            "shelf_life": shelf_life_days,
        }

    def list_price(self, sku):
        item = self._item(sku)
        return money.list_price(item["unit_cost"], self.rounding_mode)  # C08

    # ------------------------------------------------------------------
    # stock movements
    def receive(self, sku, qty, wh):
        return self._mutate(self._do_receive_public, sku, qty, wh)

    def receive_bulk(self, receipts):
        """C24: all-or-nothing list of (sku, qty, wh)."""
        return self._mutate(self._do_bulk, receipts)

    def _do_bulk(self, receipts):
        try:
            receipts = list(receipts)
        except TypeError:
            raise DepotError("BAD_ARG")
        for r in receipts:
            try:
                sku, qty, wh = r
            except (TypeError, ValueError):
                raise DepotError("BAD_ARG")
            self._do_receive_public(sku, qty, wh)

    def ship(self, sku, qty, wh, price):
        return self._mutate(self._do_ship, sku, qty, wh, price)

    def _do_ship(self, sku, qty, wh, price):
        self._item(sku)
        self._wh(wh)
        self._check_qty(qty)
        if not _is_int(price) or price < 0:
            raise DepotError("BAD_ARG")
        if self._sku_wh_units(sku, wh) < qty:                   # C06
            raise DepotError("INSUFFICIENT_STOCK")
        self._take_fifo(sku, wh, qty)                           # C12
        revenue = money.sale_revenue(price, qty, self.rounding_mode)  # C07, C09
        self.ledger.cash += revenue
        self.ledger.shipments.append((self._day, qty))
        self.sold_by_sku[sku] = self.sold_by_sku.get(sku, 0) + qty
        self._reorder_check(sku, wh, outflow=True)
        return revenue

    def transfer(self, sku, qty, from_wh, to_wh):
        return self._mutate(self._do_transfer, sku, qty, from_wh, to_wh)

    def _do_transfer(self, sku, qty, from_wh, to_wh):
        self._item(sku)
        self._wh(from_wh)
        self._wh(to_wh)
        self._check_qty(qty)
        if from_wh == to_wh:
            raise DepotError("SAME_WAREHOUSE")
        if self._sku_wh_units(sku, from_wh) < qty:              # C10
            raise DepotError("INSUFFICIENT_STOCK")
        if self._wh_total(to_wh) + qty > self.capacities[to_wh]:
            raise DepotError("CAPACITY")
        cost = money.transfer_cost(qty)                         # C11
        if self.ledger.cash - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        taken = self._take_fifo(sku, from_wh, qty)
        dest = self.lots.setdefault((sku, to_wh), [])
        for day, units in taken:
            dest.append([day, units])                           # keep receipt day
        dest.sort(key=lambda lot: lot[0])
        self.ledger.cash -= cost
        self._reorder_check(sku, from_wh, outflow=True)
        self._reorder_check(sku, to_wh, outflow=False)

    def return_goods(self, sku, qty, wh, price):
        return self._mutate(self._do_return, sku, qty, wh, price)

    def _do_return(self, sku, qty, wh, price):
        self._item(sku)
        self._wh(wh)
        self._check_qty(qty)
        if not _is_int(price) or price < 0:
            raise DepotError("BAD_ARG")
        outstanding = self.sold_by_sku.get(sku, 0) - self.returned_by_sku.get(sku, 0)
        if qty > outstanding:                                   # C23
            raise DepotError("RETURN_EXCEEDS")
        if self._wh_total(wh) + qty > self.capacities[wh]:
            raise DepotError("CAPACITY")
        # NOTE: returned goods are restocked as a new lot stamped today (C23).
        self.lots.setdefault((sku, wh), []).append([self._day, qty])
        self.returned_by_sku[sku] = self.returned_by_sku.get(sku, 0) + qty
        self.ledger.cash += price * qty
        self._reorder_check(sku, wh, outflow=False)

    # ------------------------------------------------------------------
    # day end
    def advance_day(self):
        """C21: storage charge, then expiry, then overdrawn check. Clears undo (C27)."""
        return self._mutate(self._do_advance, undoable=False)

    def _do_advance(self):
        units = self._total_units()
        self.ledger.holdings[self._day] = units
        self.ledger.cash -= money.storage_charge(units)         # C19
        new_day = self._day + 1
        for sku in sorted(self.items):                          # C13
            shelf = self.items[sku]["shelf_life"]
            if shelf is None or shelf < 1:
                continue
            for wh in self.warehouses:
                key = (sku, wh)
                lots = self.lots.get(key)
                if not lots:
                    continue
                expired = sum(q for d, q in lots if new_day - d > shelf)
                if expired:
                    self.lots[key] = [lot for lot in lots if new_day - lot[0] <= shelf]
                    self.log.emit("EXPIRY", sku, wh, expired)
                    self._reorder_check(sku, wh, outflow=False)
        if self.ledger.cash < 0:                                # C20
            self.log.emit("OVERDRAWN")
        self._day += 1

    # ------------------------------------------------------------------
    # queries
    def stock(self, sku, wh=None):
        self._item(sku)
        if wh is None:
            return sum(self._sku_wh_units(sku, w) for w in self.warehouses)  # C25
        self._wh(wh)
        return self._sku_wh_units(sku, wh)

    def report(self):
        """C26: rows (sku, wh, units, value_cents) sorted by sku then wh. Only non-empty positions."""
        rows = []
        for sku, wh in sorted(self.lots):
            units = self._sku_wh_units(sku, wh)
            if units > 0:
                rows.append((sku, wh, units, units * self.items[sku]["unit_cost"]))
        return rows

    def notifications(self):
        return self.log.items()                                 # C32

    def turnover(self, start_day, end_day):
        if not _is_int(start_day) or not _is_int(end_day):
            raise DepotError("BAD_ARG")
        return self.ledger.turnover(start_day, end_day)         # C30

    # ------------------------------------------------------------------
    # audit
    def audit(self, counts):
        return self._mutate(self._do_audit, counts)

    def _do_audit(self, counts):
        """C22: emit AUDIT_MISMATCH for each mismatch; does not change stock."""
        if not counts:
            raise DepotError("EMPTY_AUDIT")
        checked = []
        for key, counted in counts.items():
            sku, wh = _pair(key)
            self._item(sku)
            self._wh(wh)
            if not _is_int(counted) or counted < 0:
                raise DepotError("BAD_ARG")
            checked.append((sku, wh, counted))
        for sku, wh, counted in sorted(checked, key=lambda p: (p[0], p[1])):
            ledger = self._sku_wh_units(sku, wh)
            if counted != ledger:
                self.log.emit("AUDIT_MISMATCH", sku, wh, ledger, counted)

    # ------------------------------------------------------------------
    # suppliers
    def place_order(self, supplier, sku, qty, due_day, wh):
        return self._mutate(self._do_place_order, supplier, sku, qty, due_day, wh)

    def _do_place_order(self, supplier, sku, qty, due_day, wh):
        self._item(sku)
        self._wh(wh)
        self._check_qty(qty)
        if not _is_int(due_day):
            raise DepotError("BAD_ARG")
        self.suppliers.check_orderable(supplier)                # C17
        return self.suppliers.add_order(supplier, sku, qty, due_day, wh)

    def deliver(self, order_id, day):
        return self._mutate(self._do_deliver, order_id, day)

    def _do_deliver(self, order_id, day):
        if not _is_int(day):
            raise DepotError("BAD_ARG")
        o = self.suppliers.open_order(order_id)
        base = self.items[o["sku"]]["unit_cost"] * o["qty"]
        late = day > o["due_day"]                               # C16
        if late:
            if self.late_penalty_pct is None:
                # C18: the penalty percentage is the owner's decision; refuse rather than guess.
                raise DepotError("PENALTY_UNSET")
            paid = money.to_cents(
                Decimal(base) * (100 - self.late_penalty_pct) / 100, self.rounding_mode
            )
        else:
            paid = base
        self._do_receive(o["sku"], o["qty"], o["wh"], paid)
        old, new = self.suppliers.adjust(o["supplier"], late)   # C15
        if old > 1 and new <= 1:
            self.log.emit("SUPPLIER_SUSPENDED", o["supplier"])  # C17
        self.suppliers.mark_delivered(order_id)

    def reliability(self, supplier):
        return self.suppliers.reliability(supplier)

    def reinstate(self, supplier):
        return self._mutate(self.suppliers.reinstate, supplier)

    # ------------------------------------------------------------------
    # persistence (C28)
    def save(self):
        data = {
            "version": 1,
            "warehouses": self.warehouses,
            "capacities": self.capacities,
            "rounding_mode": self.rounding_mode,
            "late_penalty_pct": None if self.late_penalty_pct is None else str(self.late_penalty_pct),
            "cash": self.ledger.cash,
            "day": self._day,
            "items": {sku: dict(v) for sku, v in sorted(self.items.items())},
            "lots": [
                [sku, wh, [[d, q] for d, q in lots]]
                for (sku, wh), lots in sorted(self.lots.items())
            ],
            "armed": [[sku, wh, flag] for (sku, wh), flag in sorted(self.armed.items())],
            "sold": dict(sorted(self.sold_by_sku.items())),
            "returned": dict(sorted(self.returned_by_sku.items())),
            "shipments": [[d, q] for d, q in self.ledger.shipments],
            "holdings": [[d, u] for d, u in sorted(self.ledger.holdings.items())],
            "suppliers": self.suppliers.to_dict(),
            "notifications": [list(n) for n in self.log.items()],
        }
        return json.dumps(data, sort_keys=True)

    def load(self, s):
        """Replace state with a saved one. Warehouses and capacities must match
        this depot's construction. On any error nothing changes."""
        try:
            data = json.loads(s)
        except (TypeError, ValueError):
            raise DepotError("BAD_SAVE")
        if not isinstance(data, dict) or data.get("version") != 1:
            raise DepotError("BAD_SAVE")
        try:
            new = self._parse_save(data)
        except (KeyError, TypeError, ValueError, AttributeError, IndexError):
            raise DepotError("BAD_SAVE")
        self.__dict__.update(new)
        self._undo = None

    def _parse_save(self, data):
        if data["warehouses"] != self.warehouses or data["capacities"] != self.capacities:
            raise ValueError("warehouse layout differs")
        items = {}
        for sku, v in data["items"].items():
            shelf = v["shelf_life"]
            items[str(sku)] = {
                "unit_cost": _need_int(v["unit_cost"]),
                "reorder_level": _need_int(v["reorder_level"]),
                "shelf_life": None if shelf is None else _need_int(shelf),
            }
        lots = {}
        for sku, wh, entries in data["lots"]:
            if sku not in items or wh not in self.capacities:
                raise ValueError("lot refers to unknown sku/warehouse")
            lots[(sku, wh)] = [[_need_int(d), _need_int(q)] for d, q in entries]
        armed = {}
        for sku, wh, flag in data["armed"]:
            if not isinstance(flag, bool):
                raise ValueError("bad armed flag")
            armed[(sku, wh)] = flag
        ledger = Ledger(_need_int(data["cash"]))
        ledger.shipments = [(_need_int(d), _need_int(q)) for d, q in data["shipments"]]
        ledger.holdings = {_need_int(d): _need_int(u) for d, u in data["holdings"]}
        return {
            "items": items,
            "lots": lots,
            "armed": armed,
            "sold_by_sku": {str(k): _need_int(v) for k, v in data["sold"].items()},
            "returned_by_sku": {str(k): _need_int(v) for k, v in data["returned"].items()},
            "ledger": ledger,
            "suppliers": Suppliers.from_dict(data["suppliers"]),
            "log": EventLog(
                [tuple(n) for n in data["notifications"]]
            ),
            "_day": _need_int(data["day"]),
        }
