"""Demand simulation (C29): customer orders drawn from the data table's demand ranges."""

import pathlib
import random
import tomllib

_DATA = tomllib.loads(
    (pathlib.Path(__file__).resolve().parent / "data.toml").read_text(encoding="utf-8")
)
_DEMAND = {
    sku: (int(v["min"]), int(v["max"])) for sku, v in sorted(_DATA["demand"].items())
}


def simulate(days, seed):
    """Return a list with one entry per day; each entry is a list of (sku, qty) orders.

    Uses only a RNG seeded with `seed`, so the same seed gives the same orders.
    A sku with a drawn quantity of 0 produces no order that day.
    """
    if not isinstance(days, int) or isinstance(days, bool) or days < 0:
        raise ValueError("days must be a non-negative int")
    rng = random.Random(seed)
    plan = []
    for _ in range(days):
        day_orders = []
        for sku, (lo, hi) in _DEMAND.items():
            qty = rng.randint(lo, hi)
            if qty > 0:
                day_orders.append((sku, qty))
        plan.append(day_orders)
    return plan
