"""Independent reference implementation of the Depot spec, for differential testing.

Exposes the same interface as the main modules: Depot, DepotError, simulate.

It shares no code with inventory.py, money.py, suppliers.py, events.py or
sim.py, and reads data.toml itself. Its structure differs on purpose:
- all mutable state lives in one JSON-friendly dict;
- each mutating operation runs on a deep copy of that dict and replaces the
  live state only if it succeeds, so atomicity holds by construction;
- lots are flat rows [sku, wh, day, qty];
- REORDER arming is a list of disarmed [sku, wh] pairs.

Where the spec is silent or undecided, this follows the decisions the main
implementation already records, so a difference points at a bug rather than a
policy disagreement:
- late penalty defaults to None, so late deliveries give PENALTY_UNSET (C18);
- a transfer that would take cash below 0 is refused with INSUFFICIENT_FUNDS;
- transfers emit REORDER on the source side only;
- OVERDRAWN is emitted at every advance_day while cash is below 0;
- returns are restocked as a new lot dated today and count against capacity;
- SAME_WAREHOUSE and BAD_ARG for non-positive quantities.
"""

import copy
import decimal
import json
import pathlib
import random
import tomllib
from decimal import Decimal
from fractions import Fraction

__all__ = ["Depot", "DepotError", "simulate"]

_CFG = tomllib.loads(
    (pathlib.Path(__file__).resolve().parent / "data.toml").read_text(encoding="utf-8")
)
_MARKUP = Decimal(str(_CFG["markup"]))
_BULK_MIN = int(_CFG["bulk_threshold"])
_BULK_PCT = Decimal(str(_CFG["bulk_discount_pct"]))
_STORAGE = int(_CFG["storage_cents_per_unit_day"])
_TRANSFER = int(_CFG["transfer_credit_cents_per_unit"])
_DEMAND = sorted(
    (sku, int(v["min"]), int(v["max"])) for sku, v in _CFG["demand"].items()
)

_MODES = frozenset((
    decimal.ROUND_UP,
    decimal.ROUND_DOWN,
    decimal.ROUND_CEILING,
    decimal.ROUND_FLOOR,
    decimal.ROUND_HALF_UP,
    decimal.ROUND_HALF_DOWN,
    decimal.ROUND_HALF_EVEN,
    decimal.ROUND_05UP,
))

_START_REL = 3
_REL_MIN = 0
_REL_MAX = 5
_REINSTATE_REL = 2
_SUSPEND_AT = 1

_STATE_KEYS = frozenset({
    "cash", "day", "items", "lots", "disarmed", "sold", "returned",
    "shipments", "holdings", "suppliers", "orders", "next_order", "notes",
})


class DepotError(Exception):
    """A failed depot operation. `code` is a string such as "CAPACITY"."""

    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _fail(code):
    raise DepotError(code)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _to_cents(amount, mode):
    return int(Decimal(amount).quantize(Decimal(1), rounding=mode))


def _lot_units(s, sku=None, wh=None):
    return sum(
        r[3]
        for r in s["lots"]
        if (sku is None or r[0] == sku) and (wh is None or r[1] == wh)
    )


def _take_oldest(s, sku, wh, qty):
    """Remove qty units oldest-first from (sku, wh). Returns [(day, taken), ...]."""
    rows = sorted(
        (r for r in s["lots"] if r[0] == sku and r[1] == wh),
        key=lambda r: r[2],
    )
    taken = []
    need = qty
    for r in rows:
        if need == 0:
            break
        t = min(r[3], need)
        taken.append((r[2], t))
        r[3] -= t
        need -= t
    s["lots"] = [r for r in s["lots"] if r[3] > 0]
    return taken


def _arm(s, sku, wh, outflow):
    """C14: emit REORDER once per fall through the level; re-arm when above it."""
    level = s["items"][sku]["reorder"]
    key = [sku, wh]
    if _lot_units(s, sku, wh) > level:
        if key in s["disarmed"]:
            s["disarmed"].remove(key)
    elif outflow and key not in s["disarmed"]:
        s["disarmed"].append(key)
        s["notes"].append(["REORDER", sku, wh])


def simulate(days, seed):
    """C29: one entry per day, each a list of (sku, qty) orders.

    Deliberately the same draw sequence as sim.py, so the two can be compared
    directly. This is therefore not an independent check of the demand logic.
    """
    if not _is_int(days) or days < 0:
        raise ValueError("days must be a non-negative int")
    rng = random.Random(seed)
    plan = []
    for _ in range(days):
        orders = []
        for sku, lo, hi in _DEMAND:
            q = rng.randint(lo, hi)
            if q > 0:
                orders.append((sku, q))
        plan.append(orders)
    return plan


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode,
                 late_penalty_pct=None):
        if rounding_mode not in _MODES:
            raise ValueError("rounding_mode")
        whs = list(warehouses)
        if not whs or len(set(whs)) != len(whs):
            raise ValueError("warehouses")
        if set(capacities) != set(whs):
            raise ValueError("capacities")
        for c in capacities.values():
            if not _is_int(c) or c < 0:
                raise ValueError("capacity")
        if not _is_int(opening_cash):
            raise ValueError("opening_cash")
        pct = None
        if late_penalty_pct is not None:
            pct = Decimal(str(late_penalty_pct))
            if not (0 <= pct <= 100):
                raise ValueError("late_penalty_pct")

        self._whs = whs
        self._caps = dict(capacities)
        self._mode = rounding_mode
        self._pct = pct
        self._s = {
            "cash": opening_cash,
            "day": 0,
            "items": {},
            "lots": [],
            "disarmed": [],
            "sold": {},
            "returned": {},
            "shipments": [],
            "holdings": [],
            "suppliers": {},
            "orders": [],
            "next_order": 1,
            "notes": [],
        }
        self._prev = None

    # ------------------------------------------------------------------
    # plumbing
    def _mutate(self, op, *args, undoable=True):
        work = copy.deepcopy(self._s)
        result = op(work, *args)          # raises DepotError -> live state untouched
        self._prev = self._s if undoable else None
        self._s = work
        return result

    def _need_item(self, s, sku):
        if sku not in s["items"]:
            _fail("UNKNOWN_SKU")
        return s["items"][sku]

    def _need_wh(self, wh):
        if wh not in self._caps:
            _fail("UNKNOWN_WAREHOUSE")

    @staticmethod
    def _need_qty(qty):
        if not _is_int(qty) or qty <= 0:
            _fail("BAD_ARG")

    def _receive_core(self, s, sku, qty, wh, cost):
        if s["cash"] < 0:
            _fail("OVERDRAWN")
        if _lot_units(s, None, wh) + qty > self._caps[wh]:
            _fail("CAPACITY")
        if s["cash"] - cost < 0:
            _fail("INSUFFICIENT_FUNDS")
        s["lots"].append([sku, wh, s["day"], qty])
        s["cash"] -= cost
        _arm(s, sku, wh, False)

    # ------------------------------------------------------------------
    # read-only properties
    @property
    def cash(self):
        return self._s["cash"]

    @property
    def day(self):
        return self._s["day"]

    # ------------------------------------------------------------------
    # catalogue
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        self._mutate(self._op_add_item, sku, unit_cost, reorder_level, shelf_life_days)

    def _op_add_item(self, s, sku, unit_cost, reorder_level, shelf_life_days):
        if not isinstance(sku, str) or sku == "":
            _fail("BAD_ARG")
        if not _is_int(unit_cost) or unit_cost <= 0:
            _fail("BAD_ARG")
        if not _is_int(reorder_level) or reorder_level < 0:
            _fail("BAD_ARG")
        if shelf_life_days is not None and (
            not _is_int(shelf_life_days) or shelf_life_days < 0
        ):
            _fail("BAD_ARG")
        if sku in s["items"]:
            _fail("DUPLICATE_SKU")
        s["items"][sku] = {
            "cost": unit_cost,
            "reorder": reorder_level,
            "shelf": shelf_life_days,
        }

    def list_price(self, sku):
        item = self._need_item(self._s, sku)
        return _to_cents(Decimal(item["cost"]) * (1 + _MARKUP), self._mode)

    # ------------------------------------------------------------------
    # receipts
    def receive(self, sku, qty, wh):
        self._mutate(self._op_receive, sku, qty, wh)

    def _op_receive(self, s, sku, qty, wh):
        item = self._need_item(s, sku)
        self._need_wh(wh)
        self._need_qty(qty)
        self._receive_core(s, sku, qty, wh, item["cost"] * qty)

    def receive_bulk(self, receipts):
        self._mutate(self._op_receive_bulk, receipts)

    def _op_receive_bulk(self, s, receipts):
        try:
            rows = list(receipts)
        except TypeError:
            _fail("BAD_ARG")
        for r in rows:
            try:
                sku, qty, wh = r
            except (TypeError, ValueError):
                _fail("BAD_ARG")
            self._op_receive(s, sku, qty, wh)

    # ------------------------------------------------------------------
    # sales, transfers, returns
    def ship(self, sku, qty, wh, price):
        return self._mutate(self._op_ship, sku, qty, wh, price)

    def _op_ship(self, s, sku, qty, wh, price):
        self._need_item(s, sku)
        self._need_wh(wh)
        self._need_qty(qty)
        if not _is_int(price) or price < 0:
            _fail("BAD_ARG")
        if _lot_units(s, sku, wh) < qty:
            _fail("INSUFFICIENT_STOCK")
        _take_oldest(s, sku, wh, qty)
        gross = Decimal(price) * qty
        if qty >= _BULK_MIN:
            gross = gross * (Decimal(100) - _BULK_PCT) / Decimal(100)
        revenue = _to_cents(gross, self._mode)
        s["cash"] += revenue
        s["shipments"].append([s["day"], qty])
        s["sold"][sku] = s["sold"].get(sku, 0) + qty
        _arm(s, sku, wh, True)
        return revenue

    def transfer(self, sku, qty, from_wh, to_wh):
        self._mutate(self._op_transfer, sku, qty, from_wh, to_wh)

    def _op_transfer(self, s, sku, qty, frm, to):
        self._need_item(s, sku)
        self._need_wh(frm)
        self._need_wh(to)
        self._need_qty(qty)
        if frm == to:
            _fail("SAME_WAREHOUSE")
        if _lot_units(s, sku, frm) < qty:
            _fail("INSUFFICIENT_STOCK")
        if _lot_units(s, None, to) + qty > self._caps[to]:
            _fail("CAPACITY")
        cost = _TRANSFER * qty
        if s["cash"] - cost < 0:
            _fail("INSUFFICIENT_FUNDS")
        for day, n in _take_oldest(s, sku, frm, qty):
            s["lots"].append([sku, to, day, n])      # keeps the receipt day
        s["cash"] -= cost
        _arm(s, sku, frm, True)
        _arm(s, sku, to, False)

    def return_goods(self, sku, qty, wh, price):
        self._mutate(self._op_return, sku, qty, wh, price)

    def _op_return(self, s, sku, qty, wh, price):
        self._need_item(s, sku)
        self._need_wh(wh)
        self._need_qty(qty)
        if not _is_int(price) or price < 0:
            _fail("BAD_ARG")
        outstanding = s["sold"].get(sku, 0) - s["returned"].get(sku, 0)
        if qty > outstanding:
            _fail("RETURN_EXCEEDS")
        if _lot_units(s, None, wh) + qty > self._caps[wh]:
            _fail("CAPACITY")
        s["lots"].append([sku, wh, s["day"], qty])
        s["returned"][sku] = s["returned"].get(sku, 0) + qty
        s["cash"] += price * qty
        _arm(s, sku, wh, False)

    # ------------------------------------------------------------------
    # day end
    def advance_day(self):
        self._mutate(self._op_advance, undoable=False)

    def _op_advance(self, s):
        units = _lot_units(s)
        s["holdings"].append([s["day"], units])
        s["cash"] -= _STORAGE * units                       # C19
        new_day = s["day"] + 1
        for sku in sorted(s["items"]):                      # C13 expiry
            shelf = s["items"][sku]["shelf"]
            if shelf is None or shelf < 1:
                continue
            for wh in self._whs:
                def expired(r, sku=sku, wh=wh, shelf=shelf):
                    return r[0] == sku and r[1] == wh and new_day - r[2] > shelf
                gone = sum(r[3] for r in s["lots"] if expired(r))
                if gone:
                    s["lots"] = [r for r in s["lots"] if not expired(r)]
                    s["notes"].append(["EXPIRY", sku, wh, gone])
                    _arm(s, sku, wh, False)
        if s["cash"] < 0:                                   # C20
            s["notes"].append(["OVERDRAWN"])
        s["day"] = new_day

    # ------------------------------------------------------------------
    # queries
    def stock(self, sku, wh=None):
        s = self._s
        self._need_item(s, sku)
        if wh is None:
            return _lot_units(s, sku)
        self._need_wh(wh)
        return _lot_units(s, sku, wh)

    def report(self):
        s = self._s
        keys = sorted({(r[0], r[1]) for r in s["lots"]})
        rows = []
        for sku, wh in keys:
            units = _lot_units(s, sku, wh)
            if units > 0:
                rows.append((sku, wh, units, units * s["items"][sku]["cost"]))
        return rows

    def notifications(self):
        return [tuple(n) for n in self._s["notes"]]

    def turnover(self, start_day, end_day):
        if not _is_int(start_day) or not _is_int(end_day) or start_day > end_day:
            _fail("BAD_ARG")
        s = self._s
        shipped = sum(q for d, q in s["shipments"] if start_day <= d <= end_day)
        held = [u for d, u in s["holdings"] if start_day <= d <= end_day]
        total = sum(held)
        if not held or total == 0:
            return None
        return float(Fraction(shipped * len(held), total))

    # ------------------------------------------------------------------
    # audit
    def audit(self, counts):
        self._mutate(self._op_audit, counts)

    def _op_audit(self, s, counts):
        if not counts:
            _fail("EMPTY_AUDIT")
        checked = []
        for key, counted in counts.items():
            try:
                sku, wh = key
            except (TypeError, ValueError):
                _fail("BAD_ARG")
            self._need_item(s, sku)
            self._need_wh(wh)
            if not _is_int(counted) or counted < 0:
                _fail("BAD_ARG")
            checked.append((sku, wh, counted))
        for sku, wh, counted in sorted(checked, key=lambda c: (c[0], c[1])):
            ledger = _lot_units(s, sku, wh)
            if ledger != counted:
                s["notes"].append(["AUDIT_MISMATCH", sku, wh, ledger, counted])

    # ------------------------------------------------------------------
    # suppliers
    def place_order(self, supplier, sku, qty, due_day, wh):
        return self._mutate(self._op_place_order, supplier, sku, qty, due_day, wh)

    def _op_place_order(self, s, supplier, sku, qty, due_day, wh):
        self._need_item(s, sku)
        self._need_wh(wh)
        self._need_qty(qty)
        if not _is_int(due_day):
            _fail("BAD_ARG")
        if supplier in s["suppliers"] and s["suppliers"][supplier] <= _SUSPEND_AT:
            _fail("SUPPLIER_SUSPENDED")                     # C17
        s["suppliers"].setdefault(supplier, _START_REL)     # C15
        oid = s["next_order"]
        s["next_order"] += 1
        s["orders"].append({
            "id": oid,
            "supplier": supplier,
            "sku": sku,
            "qty": qty,
            "due": due_day,
            "wh": wh,
            "done": False,
        })
        return oid

    def deliver(self, order_id, day):
        self._mutate(self._op_deliver, order_id, day)

    def _op_deliver(self, s, order_id, day):
        if not _is_int(day):
            _fail("BAD_ARG")
        order = next((o for o in s["orders"] if o["id"] == order_id), None)
        if order is None:
            _fail("UNKNOWN_ORDER")
        if order["done"]:
            _fail("ORDER_CLOSED")
        item = s["items"][order["sku"]]
        base = item["cost"] * order["qty"]
        late = day > order["due"]                           # C16
        if late:
            if self._pct is None:
                _fail("PENALTY_UNSET")                      # C18: undecided
            paid = _to_cents(
                Decimal(base) * (Decimal(100) - self._pct) / Decimal(100),
                self._mode,
            )
        else:
            paid = base
        self._receive_core(s, order["sku"], order["qty"], order["wh"], paid)
        name = order["supplier"]
        old = s["suppliers"][name]
        new = max(_REL_MIN, min(_REL_MAX, old + (-1 if late else 1)))   # C15
        s["suppliers"][name] = new
        if old > _SUSPEND_AT and new <= _SUSPEND_AT:
            s["notes"].append(["SUPPLIER_SUSPENDED", name])  # C17
        order["done"] = True

    def reinstate(self, supplier):
        self._mutate(self._op_reinstate, supplier)

    def _op_reinstate(self, s, supplier):
        if supplier not in s["suppliers"]:
            _fail("UNKNOWN_SUPPLIER")
        s["suppliers"][supplier] = _REINSTATE_REL

    def reliability(self, supplier):
        if supplier not in self._s["suppliers"]:
            _fail("UNKNOWN_SUPPLIER")
        return self._s["suppliers"][supplier]

    # ------------------------------------------------------------------
    # undo (C27)
    def undo(self):
        if self._prev is None:
            _fail("UNDO_BLOCKED")
        self._s = self._prev
        self._prev = None

    # ------------------------------------------------------------------
    # persistence (C28)
    def save(self):
        return json.dumps(
            {
                "version": 1,
                "layout": {"warehouses": self._whs, "capacities": self._caps},
                "state": self._s,
            },
            sort_keys=True,
        )

    def load(self, text):
        try:
            data = json.loads(text)
        except (TypeError, ValueError):
            _fail("BAD_SAVE")
        if not isinstance(data, dict) or data.get("version") != 1:
            _fail("BAD_SAVE")
        if data.get("layout") != {"warehouses": self._whs, "capacities": self._caps}:
            _fail("BAD_SAVE")
        state = data.get("state")
        if not self._valid_state(state):
            _fail("BAD_SAVE")
        self._s = state
        self._prev = None

    def _valid_state(self, st):
        try:
            if not isinstance(st, dict) or set(st) != _STATE_KEYS:
                return False
            if not all(_is_int(st[k]) for k in ("cash", "day", "next_order")):
                return False
            items = st["items"]
            if not isinstance(items, dict):
                return False
            for v in items.values():
                if not isinstance(v, dict):
                    return False
                if not (_is_int(v.get("cost")) and _is_int(v.get("reorder"))):
                    return False
                if v.get("shelf") is not None and not _is_int(v.get("shelf")):
                    return False
            for r in st["lots"]:
                if not (isinstance(r, list) and len(r) == 4):
                    return False
                if not (r[0] in items and r[1] in self._caps):
                    return False
                if not (_is_int(r[2]) and _is_int(r[3]) and r[3] > 0):
                    return False
            for r in st["disarmed"]:
                if not (isinstance(r, list) and len(r) == 2 and r[0] in items and r[1] in self._caps):
                    return False
            for key in ("shipments", "holdings"):
                for r in st[key]:
                    if not (isinstance(r, list) and len(r) == 2 and _is_int(r[0]) and _is_int(r[1])):
                        return False
            for key in ("sold", "returned", "suppliers"):
                if not (isinstance(st[key], dict) and all(_is_int(v) for v in st[key].values())):
                    return False
            for o in st["orders"]:
                if not (isinstance(o, dict) and "id" in o and "done" in o):
                    return False
            for n in st["notes"]:
                if not (isinstance(n, list) and n and isinstance(n[0], str)):
                    return False
            return True
        except (TypeError, KeyError, AttributeError):
            return False
